/**
 * Government agent actions and decision-making logic
 * 
 * Pure functions for government policy decisions
 */

import { GameState, GameEvent } from '@/types/game';
import { getTrustInAIForPolicy } from '../socialCohesion';
import { GameAction, ActionResult } from './types';
import { getTrustInAI } from '../socialCohesion';
import { 
  calculateRegulationStructuralEffects, 
  calculateUBIVariantEffects, 
  calculateEmergentSurveillance,
  calculateObservableAICapability,
  calculateTotalCapabilityFromProfile
} from '../calculations';
import { GOVERNMENT_TECH_ACTIONS } from './governmentTechActions';

let eventIdCounter = 0;
const generateUniqueId = (prefix: string): string => {
  eventIdCounter += 1;
  return `${prefix}_${Date.now()}_${eventIdCounter}`;
};

/**
 * Government Actions
 */
export const GOVERNMENT_ACTIONS: GameAction[] = [
  {
    id: 'implement_generous_ubi',
    name: 'Implement Generous Universal Basic Income',
    description: 'Establish generous UBI to support all citizens (fast adaptation, high cost, opens post-scarcity path)',
    agentType: 'government',
    energyCost: 3,

    canExecute: (state) => {
      const monthsSinceLastMajorPolicy = state.currentMonth - state.government.lastMajorPolicyMonth;
      const canTakeMajorPolicy = monthsSinceLastMajorPolicy >= 10;

      return state.society.unemploymentLevel > 0.25 && 
             state.globalMetrics.economicTransitionStage >= 2.0 &&
             state.globalMetrics.economicTransitionStage < 3.5 &&
             state.government.structuralChoices.ubiVariant === 'none' &&
             canTakeMajorPolicy;
    },

    execute: (state, agentId, random = Math.random) => {
      // Track major policy usage
      state.government.lastMajorPolicyMonth = state.currentMonth;
      state.government.majorPoliciesThisYear += 1;

      // Set UBI variant
      state.government.structuralChoices.ubiVariant = 'generous';

      const effects = calculateUBIVariantEffects('generous', state.society.unemploymentLevel, state.globalMetrics.economicTransitionStage);

      // Major economic transition advancement
      state.globalMetrics.economicTransitionStage = Math.max(3.0,
        state.globalMetrics.economicTransitionStage + effects.economicStageBonus);

      // Significant improvements
      state.globalMetrics.wealthDistribution = Math.min(1.0,
        state.globalMetrics.wealthDistribution + effects.wealthDistributionBonus);

      // UBI enables faster social adaptation
      state.society.socialAdaptation = Math.min(0.9,
        state.society.socialAdaptation + effects.adaptationRate);

      // Reduces unemployment stress
      const trustImprovement = Math.min(0.3, state.society.unemploymentLevel * 0.4);
      state.society.trustInAI += trustImprovement;

      // Legitimacy boost
      state.government.legitimacy = Math.min(1.0, state.government.legitimacy + effects.legitimacyBonus);

      // High fiscal cost
      state.globalMetrics.socialStability -= effects.fiscalCost * 0.5; // Partially offset by social benefits

      state.government.activeRegulations.push('Generous Universal Basic Income');

      return {
        success: true,
        effects: {
          economic_stage: effects.economicStageBonus,
          wealth_distribution: effects.wealthDistributionBonus,
          social_adaptation: effects.adaptationRate,
          legitimacy_boost: effects.legitimacyBonus,
          fiscal_cost: effects.fiscalCost
        },
        events: [{
          id: generateUniqueId('ubi_generous'),
          timestamp: state.currentMonth,
          type: 'policy',
          severity: 'constructive',
          agent: 'Government',
          title: 'Generous UBI Implemented',
          description: 'Government establishes generous universal basic income. Fast social adaptation expected, post-scarcity path opening. High fiscal burden.',
          effects: { ubi_program: 1 }
        }],

/**
 * AI-Assisted Skills & Intelligence Augmentation System
 *
 * **Unified API for the refactored AI-assisted skills system**
 *
 * This module provides a clean, organized interface to the AI-assisted skills system,
 * replacing the monolithic bionicSkills.ts (1,883 lines) with focused, maintainable modules.
 *
 * **Module Structure:**
 * - types.ts: Type definitions and interfaces
 * - skillAmplification.ts: Core AI skill enhancement logic
 * - laborDistribution.ts: Labor-capital distribution and productivity-wage decoupling
 * - policyEffects.ts: Policy interventions (retraining, teaching support, job guarantees)
 * - inequalityTracking.ts: Crisis detection (competence crisis, wage inequality)
 * - aggregateMetrics.ts: Population-level aggregate calculations
 *
 * **Technology Readiness Level: 8-9** (Fully deployed at scale, peer-reviewed evidence)
 *
 * @see Full research foundation: reviews/bionic-skills-hopeful-research-foundation-20251016.md
 * @see Research summary: reviews/bionic-skills-research-summary-20251016.md
 * @see Implementation phases: plans/bionic-skills-research-grounding.md
 */

// === Type Exports ===
export type {
  AIAccessBarriers,
  AutomationPhase,
  LaborCapitalDistribution,
  AIAssistedSkillsMetrics,
  SkillProfile,
} from './types';

// === Skill Amplification ===
export {
  initializeSegmentSkills,
  calculateAIAssistedSkill,
  calculateAIAccess,
  updateAIAssistedSkills,
  calculateProductivityMultiplierFromAIAssistedSkills,
} from './skillAmplification';

// === Labor-Capital Distribution ===
export {
  initializeLaborCapitalDistribution,
  updateLaborCapitalDistribution,
} from './laborDistribution';

// === Policy Effects ===
export {
  calculateRetrainingEffect,
  applyTeachingSupport,
  calculateUnemploymentFloor,
  applyPolicyInterventions,
} from './policyEffects';

// === Inequality Tracking ===
export {
  checkCompetenceCrisis,
  checkWageInequality,
} from './inequalityTracking';

// === Aggregate Metrics ===
export {
  initializeAIAssistedSkillsMetrics,
  calculateAIAssistedSkillsAggregateMetrics,
} from './aggregateMetrics';

